package com.lamggm.rospocket;
import org.junit.*;import org.json.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class RobotTfContextTest {
 static class Api extends RobotDashboardTest.Fake {int starts,stops,polls;String writer="d";Runnable opening=()->{};public byte[] startTf(String d,String s,boolean r,boolean t){starts++;opening.run();return bytes("{\"ok\":true}");}public void stopTf(){stops++;}public byte[] pollTf(){polls++;try{return bytes(new JSONObject().put("running",true).put("rows",new JSONArray().put(RobotTfTest.edge("base","wheel",100,false,2,0,0).put("writer",writer))).toString());}catch(Exception e){throw new AssertionError(e);}}}
 static JSONArray topics()throws Exception{JSONArray a=RobotDashboardTest.topics("/r/robot_description","/r/tf");a.getJSONObject(1).put("wireType","tf2_msgs::msg::dds_::TFMessage_");return a;}
 @Test public void actualContextAcquiresIndependentTfAndBindsPosesToExactDescriptionOwner()throws Exception{RobotContext c=new RobotContext();Api api=new Api();RobotContext.Snapshot description=c.observe(api,96,"127.0.0.1","","lan","jazzy",topics(),()->true);assertNotNull(description.model);assertEquals(1,api.starts);RobotContext.PoseSnapshot p=c.pollTf(api,100);assertNotNull(p);assertTrue(c.current(p));assertEquals(description.model.fingerprint,p.fingerprint);assertTrue(p.pose.status,p.pose.live);assertEquals(2,p.pose.transforms.get("wheel")[3],0);c.select("");assertFalse(c.current(p));assertNull(c.pollTf(api,200));}
 @Test public void selectionChangedDuringAcquisitionCannotAdoptLateReader()throws Exception{RobotContext c=new RobotContext();Api api=new Api();api.opening=()->c.select("rt/other/robot_description");c.observe(api,96,"127.0.0.1","","lan","jazzy",topics(),()->true);assertEquals(1,api.starts);assertTrue(api.stops>0);assertNull(c.pollTf(api,100));}

 @Test public void discoveryReplacementCannotEraseEstablishedAuthorityUntilExplicitSelection()throws Exception{RobotContext c=new RobotContext();Api api=new Api();JSONArray original=topics();c.observe(api,96,"127.0.0.1","","lan","jazzy",original,()->true);assertTrue(c.pollTf(api,100).pose.live);JSONArray replacement=topics();replacement.getJSONObject(1).getJSONArray("endpoints").getJSONObject(0).put("id","replacement_gid");api.writer="new_writer";c.observe(api,96,"127.0.0.1","","lan","jazzy",replacement,()->true);assertFalse("Discovery must not clear authority history",c.pollTf(api,200).pose.live);assertEquals("Replacement must not be auto-acquired",1,api.starts);c.observe(api,96,"127.0.0.1","","lan","jazzy",replacement,()->true);assertFalse(c.pollTf(api,300).pose.live);c.select("");c.observe(api,96,"127.0.0.1","","lan","jazzy",replacement,()->true);assertTrue(c.pollTf(api,400).pose.live);}
 @Test public void missingTfDiscoveryDoesNotEraseAuthorityBeforeReplacement()throws Exception{RobotContext c=new RobotContext();Api api=new Api();c.observe(api,96,"127.0.0.1","","lan","jazzy",topics(),()->true);assertTrue(c.pollTf(api,100).pose.live);c.observe(api,96,"127.0.0.1","","lan","jazzy",RobotDashboardTest.topics("/r/robot_description"),()->true);JSONArray replacement=topics();replacement.getJSONObject(1).getJSONArray("endpoints").getJSONObject(0).put("id","replacement_after_gap");api.writer="replacement_after_gap";c.observe(api,96,"127.0.0.1","","lan","jazzy",replacement,()->true);assertFalse(c.pollTf(api,200).pose.live);assertEquals(1,api.starts);}

 @Test public void descriptionDiscoveryGapCannotEraseTfAuthorityBinding()throws Exception{RobotContext c=new RobotContext();Api api=new Api();c.observe(api,96,"127.0.0.1","","lan","jazzy",topics(),()->true);assertTrue(c.pollTf(api,100).pose.live);c.observe(api,96,"127.0.0.1","","lan","jazzy",new JSONArray(),()->true);JSONArray replacement=topics();replacement.getJSONObject(1).getJSONArray("endpoints").getJSONObject(0).put("id","after_description_gap");api.writer="after_description_gap";c.observe(api,96,"127.0.0.1","","lan","jazzy",replacement,()->true);assertFalse(c.pollTf(api,200).pose.live);assertEquals(1,api.starts);}
 @Test public void staticWriterReplacementHasTheSameReconnectGuard()throws Exception{RobotContext c=new RobotContext();Api api=new Api();JSONArray t=topics();JSONObject s=RobotDashboardTest.topics("/r/tf_static").getJSONObject(0).put("wireType","tf2_msgs::msg::dds_::TFMessage_");t.put(s);c.observe(api,96,"127.0.0.1","","lan","jazzy",t,()->true);assertTrue(c.pollTf(api,100).pose.live);s.getJSONArray("endpoints").getJSONObject(0).put("id","new_static_writer");c.observe(api,96,"127.0.0.1","","lan","jazzy",t,()->true);assertFalse(c.pollTf(api,200).pose.live);assertEquals(1,api.starts);}
}
